import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import './CharacterSheet.css';

const CharacterSheet = () => {
    const navigate = useNavigate();

    // Main state for the entire sheet
    const [character, setCharacter] = useState({
        name: '',
        charClass: '',
        level: 1,
        background: '',
        playerName: '',
        species: '',
        alignment: '',
        expPoints: 0,
        stats: {
            Strength: 10,
            Dexterity: 10,
            Constitution: 10,
            Intelligence: 10,
            Wisdom: 10,
            Charisma: 10
        },
        armorClass: 10,
        initiative: 0,
        speed: 30,
        hpMaximum: 10,
        currentHp: 10,
        personalityTraits: '',
        ideals: '',
        bonds: '',
        flaws: ''
    });

    // Helper function to update stats
    const handleStatChange = (statName, value) => {
        setCharacter(prev => ({
            ...prev,
            stats: { ...prev.stats, [statName]: value }
        }));
    };

    // Helper function to calculate modifiers (D&D standard formula)
    const calculateModifier = (score) => {
        const mod = Math.floor((score - 10) / 2);
        return mod > 0 ? `+${mod}` : mod;
    };

    const handleSave = async (e) => {
        e.preventDefault();
        // Here we will add the MongoDB save logic later!
        console.log("Saving Character: ", character);
        alert("Character saved! (Backend integration pending)");
    };

    return (
        <div className="sheet-bg">
            <div className="sheet-container">

                {/* --- HEADER SECTION --- */}
                <header className="sheet-header">
                    <div className="char-name-container">
                        <input 
                            type="text" 
                            placeholder="Character Name" 
                            value={character.name}
                            onChange={(e) => setCharacter({...character, name: e.target.value})}
                        />
                    </div>

                    <div className="char-details-grid">
                        <div className="detail-box">
                            <input type="text" value={character.charClass} onChange={(e) => setCharacter({...character, charClass: e.target.value})} />
                            <label>Class & Level</label>
                        </div>
                        <div className="detail-box">
                            <input type="text" value={character.background} onChange={(e) => setCharacter({...character, background: e.target.value})} />
                            <label>Background</label>
                        </div>
                        <div className="detail-box">
                            <input type="text" value={character.playerName} onChange={(e) => setCharacter({...character, playerName: e.target.value})} />
                            <label>Player Name</label>
                        </div>
                        <div className="detail-box">
                            <input type="text" value={character.species} onChange={(e) => setCharacter({...character, species: e.target.value})} />
                            <label>Race / Species</label>
                        </div>
                        <div className="detail-box">
                            <input type="text" value={character.alignment} onChange={(e) => setCharacter({...character, alignment: e.target.value})} />
                            <label>Alignment</label>
                        </div>
                        <div className="detail-box">
                            <input type="number" value={character.expPoints} onChange={(e) => setCharacter({...character, expPoints: e.target.value})} />
                            <label>Experience Points</label>
                        </div>
                    </div>
                </header>

                {/* --- MAIN 3-COLUMN LAYOUT --- */}
                <form className="sheet-body" onSubmit={handleSave}>

                    {/* COLUMN 1: STATS & SKILLS */}
                    <div className="col-left">
                        <div className="stats-wrapper">
                            {/* Modular mapping for all 6 core stats */}
                            {Object.keys(character.stats).map((stat) => (
                                <div className="stat-box" key={stat}>
                                    <label>{stat}</label>
                                    <div className="stat-modifier">{calculateModifier(character.stats[stat])}</div>
                                    <input 
                                        type="number" 
                                        className="stat-score"
                                        value={character.stats[stat]} 
                                        onChange={(e) => handleStatChange(stat, e.target.value)} 
                                    />
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* COLUMN 2: COMBAT (AC, HP, ATTACKS) */}
                    <div className="col-middle">
                        <div className="combat-stats-row">
                            <div className="combat-box">
                                <input type="number" value={character.armorClass} onChange={(e) => setCharacter({...character, armorClass: e.target.value})} />
                                <label>Armor Class</label>
                            </div>
                            <div className="combat-box">
                                <input type="number" value={character.initiative} onChange={(e) => setCharacter({...character, initiative: e.target.value})} />
                                <label>Initiative</label>
                            </div>
                            <div className="combat-box">
                                <input type="number" value={character.speed} onChange={(e) => setCharacter({...character, speed: e.target.value})} />
                                <label>Speed</label>
                            </div>
                        </div>

                        <div className="hp-box">
                            <div className="hp-header">
                                <span>Hit Point Maximum</span>
                                <input type="number" value={character.hpMaximum} onChange={(e) => setCharacter({...character, hpMaximum: e.target.value})} />
                            </div>
                            <input type="number" className="current-hp" value={character.currentHp} onChange={(e) => setCharacter({...character, currentHp: e.target.value})} />
                            <label>Current Hit Points</label>
                        </div>

                        <div className="attacks-box">
                            <label>Attacks & Spellcasting</label>
                            <textarea placeholder="Weapon | ATK Bonus | Damage/Type"></textarea>
                        </div>
                    </div>

                    {/* COLUMN 3: TRAITS & FEATURES */}
                    <div className="col-right">
                        <div className="trait-box">
                            <textarea value={character.personalityTraits} onChange={(e) => setCharacter({...character, personalityTraits: e.target.value})}></textarea>
                            <label>Personality Traits</label>
                        </div>
                        <div className="trait-box">
                            <textarea value={character.ideals} onChange={(e) => setCharacter({...character, ideals: e.target.value})}></textarea>
                            <label>Ideals</label>
                        </div>
                        <div className="trait-box">
                            <textarea value={character.bonds} onChange={(e) => setCharacter({...character, bonds: e.target.value})}></textarea>
                            <label>Bonds</label>
                        </div>
                        <div className="trait-box">
                            <textarea value={character.flaws} onChange={(e) => setCharacter({...character, flaws: e.target.value})}></textarea>
                            <label>Flaws</label>
                        </div>
                    </div>

                </form>

                {/* --- FOOTER ACTIONS --- */}
                <div className="sheet-actions">
                    <button type="button" className="cancel-btn" onClick={() => navigate('/character-manager')}>BACK</button>
                    <button type="submit" className="save-btn" onClick={handleSave}>SAVE CHARACTER</button>
                </div>

            </div>
        </div>
    );
};

export default CharacterSheet;
